import sailpoint.api.SailPointContext;
import sailpoint.object.Identity;
import sailpoint.tools.GeneralException;


Identity id = context.getObjectByName(Identity.class, "James.Smith");
System.out.println(id.getFirstname());
System.out.println(id.getLastname());
System.out.println(id.getEmail());
System.out.println(id.getCreated());
System.out.println(id.getModified());
System.out.println(id.getName());

String password = (id != null) ? id.getPassword() : null;
System.out.println("Password: " + password);
